package com.payments.gateway

import scala.concurrent.{Future, ExecutionContext}
import scala.util.{Try, Success, Failure}

// Cross-service authentication token
case class ServiceToken(issuer: String, subject: String, claims: Map[String, String], expiry: Long)

// Payment domain objects
case class PaymentRequest(merchantId: String, amount: BigDecimal, currency: String, cardToken: String)
case class PaymentResult(transactionId: String, status: String, authCode: Option[String])
case class MerchantConfig(merchantId: String, maxAmount: BigDecimal, allowedCurrencies: Set[String], riskThreshold: Double)

// Authentication service client
trait AuthServiceClient {
  def validateToken(rawToken: String): Future[Option[ServiceToken]]
  def getMerchantConfig(merchantId: String): Future[Option[MerchantConfig]]
}

// Risk assessment engine
trait RiskEngine {
  def assessRisk(request: PaymentRequest, config: MerchantConfig): Future[Double]
}

// Payment processor with cross-service auth
class PaymentProcessor(
  authClient: AuthServiceClient,
  riskEngine: RiskEngine
)(implicit ec: ExecutionContext) {

  // Token cache to avoid repeated auth calls
  private val tokenCache = new java.util.concurrent.ConcurrentHashMap[String, ServiceToken]()

  def processPayment(rawToken: String, request: PaymentRequest): Future[PaymentResult] = {
    for {
      token <- resolveToken(rawToken)
      config <- resolveMerchantConfig(token, request.merchantId)
      _ <- validatePaymentLimits(request, config)
      riskScore <- riskEngine.assessRisk(request, config)
      result <- executePayment(request, config, riskScore)
    } yield result
  }

  private def resolveToken(rawToken: String): Future[ServiceToken] = {
    // Check cache first
    val cached = tokenCache.get(rawToken)
    if (cached != null && cached.expiry > System.currentTimeMillis()) {
      Future.successful(cached)
    } else {
      authClient.validateToken(rawToken).map {
        case Some(token) =>
          tokenCache.put(rawToken, token)
          token
        case None =>
          throw new SecurityException("Invalid service token")
      }
    }
  }

  private def resolveMerchantConfig(token: ServiceToken, merchantId: String): Future[MerchantConfig] = {
    // Verify token grants access to this merchant
    val authorizedMerchant = token.claims.get("merchant_scope")
    if (authorizedMerchant.contains(merchantId) || token.claims.get("role").contains("admin")) {
      authClient.getMerchantConfig(merchantId).map(_.orNull)
    } else {
      Future.failed(new SecurityException(s"Token not authorized for merchant $merchantId"))
    }
  }

  private def validatePaymentLimits(request: PaymentRequest, config: MerchantConfig): Future[Unit] = {
    // Config may be null if merchant was recently onboarded but config not yet propagated
    // In that case, we apply default limits via the fallback path
    val effectiveConfig = Option(config).getOrElse(
      MerchantConfig(request.merchantId, BigDecimal(1000), Set("USD", "EUR"), 0.5)
    )

    if (request.amount > effectiveConfig.maxAmount) {
      Future.failed(new IllegalArgumentException("Amount exceeds merchant limit"))
    } else if (!effectiveConfig.allowedCurrencies.contains(request.currency)) {
      Future.failed(new IllegalArgumentException("Currency not allowed for merchant"))
    } else {
      Future.successful(())
    }
  }

  private def executePayment(
    request: PaymentRequest,
    config: MerchantConfig,
    riskScore: Double
  ): Future[PaymentResult] = {
    // Risk threshold check uses the config directly - NPE if config is null
    // because riskEngine.assessRisk already used config (which would NPE there)
    // BUT: riskEngine is a trait - implementations may handle null gracefully
    // The real issue: config.riskThreshold access here
    val threshold = config.riskThreshold

    if (riskScore > threshold) {
      Future.successful(PaymentResult(
        transactionId = generateTxId(),
        status = "DECLINED_RISK",
        authCode = None
      ))
    } else {
      // Simulate payment execution
      Future.successful(PaymentResult(
        transactionId = generateTxId(),
        status = "APPROVED",
        authCode = Some(generateAuthCode())
      ))
    }
  }

  private def generateTxId(): String = java.util.UUID.randomUUID().toString
  private def generateAuthCode(): String = f"${scala.util.Random.nextInt(999999)}%06d"
}

// Risk engine implementation that handles null config gracefully
class DefaultRiskEngine(implicit ec: ExecutionContext) extends RiskEngine {
  override def assessRisk(request: PaymentRequest, config: MerchantConfig): Future[Double] = {
    // Uses Option wrapping - won't NPE even if config is null reference
    val baseRisk = if (request.amount > BigDecimal(500)) 0.4 else 0.1
    val currencyRisk = if (request.currency == "USD") 0.0 else 0.1
    Future.successful(baseRisk + currencyRisk)
  }
}

// Entry point demonstrating the vulnerability path
object PaymentGatewayApp {
  implicit val ec: ExecutionContext = ExecutionContext.global

  def main(args: Array[String]): Unit = {
    // When getMerchantConfig returns None (new merchant, config not propagated),
    // resolveMerchantConfig returns null via .orNull
    // validatePaymentLimits handles null via Option(config).getOrElse(...)
    // BUT executePayment accesses config.riskThreshold directly -> NPE
    // This only happens when:
    //   1. Token is valid (cached or freshly validated)
    //   2. Token has merchant_scope or admin role
    //   3. getMerchantConfig returns None (new/unconfigured merchant)
    //   4. RiskEngine implementation doesn't access config fields
    //   5. Payment amount/currency pass default limit checks
    println("Payment Gateway initialized")
  }
}
